import time
import urllib.request


def timed(url):
    start = time.time()
    try:
        with urllib.request.urlopen(url, timeout=5) as r:
            return r.status, int((time.time() - start) * 1000)
    except Exception:
        return None, -1


print(timed('https://example.org'))

