import re


def manifest_kind(text):
    kind = re.search(r'^kind:\s*(\S+)', text, re.M)
    name = re.search(r'^\s+name:\s*(\S+)', text, re.M)
    return (kind.group(1) if kind else None, name.group(1) if name else None)


print(manifest_kind('kind: Deployment\n  name: app'))

