UNITS = {'Ki': 1024, 'Mi': 1024 ** 2, 'Gi': 1024 ** 3}


def parse_size(text):
    for unit, mult in UNITS.items():
        if text.endswith(unit):
            return int(float(text[:-len(unit)]) * mult)
    return int(text)


def fmt_size(num):
    for unit, mult in sorted(UNITS.items(), key=lambda x: -x[1]):
        if num >= mult and num % mult == 0:
            return '%d%s' % (num // mult, unit)
    return str(num)


print(parse_size('10Gi'), fmt_size(10737418240))

