def inventory_ini(hosts):
    lines = []
    for group, items in hosts.items():
        lines.append('[%s]' % group)
        for h in items:
            lines.append('%s ansible_host=%s' % (h['name'], h['ip']))
        lines.append('')
    return '\n'.join(lines)


print(inventory_ini({'web': [{'name': 'vm1', 'ip': '10.0.0.1'}]}))

